const actions = [
  'lay in',
  'ate',
  'killed',
  'worried',
  'tossed',
  'milked',
  'kissed',
  'married',
  'woke',
  'kept',
  'belonged to',
];

export class House {
  static verse(verseNumber) {
    const lines = [`This is ${subjects[verseNumber - 1]}`];

    for (let currentIndex = verseNumber - 1; currentIndex > 0; currentIndex -= 1) {
